const viralPosts = [
  {
    hook: '🎸 Learning guitar shouldn\'t cost $15/mo for Rocksmith+.',
    body: 'We made GRYF: 100% free, open-source web app running right in your browser.\n\n• Sub-5ms pitch detection (AudioWorklet + YIN)\n• 3D Rocksmith highway & beveled gems\n• Works with standard mic or USB audio interface\n\nDemo: http://92.118.206.90:3000\nGitHub: https://github.com/merx666/gryf-guitar',
    tags: ['#Guitar', '#OpenSource', '#Rocksmith', '#WebAudio']
  },
  {
    hook: '🔥 Drop ANY MP3 or YouTube link -> get instant guitar tabs & 3D highway sync.',
    body: 'Gryf AI Studio isolates guitar stems with Demucs v4 and aligns notes note-for-note down to 5ms.\n\n• Solo lead guitar to nail solos\n• Mute guitar to jam with real backing tracks\n\nTry live: http://92.118.206.90:3000\nCode: https://github.com/merx666/gryf-guitar',
    tags: ['#GuitarTabs', '#AI', '#Demucs', '#WebDev']
  },
  {
    hook: '⚡ Can Web Audio API replace a guitar amp?',
    body: 'Gryf features in-browser physical tube emulation, 50Hz hum filter, BBD analog stereo chorus and tape delay with zero latency.\n\nPlug your guitar directly into Chrome/Firefox:\nhttp://92.118.206.90:3000\nGitHub: https://github.com/merx666/gryf-guitar',
    tags: ['#WebAudio', '#GuitarPedals', '#DSP', '#OpenSource']
  },
  {
    hook: '🎸 Rocksmith 2014 was legendary. We brought the experience to the web.',
    body: 'True 3D perspective neck, mother-of-pearl trapezoid inlays, open-string hoops, and 4-fret hand anchor brackets.\n\n100% free & open-source:\nhttp://92.118.206.90:3000\nCode: https://github.com/merx666/gryf-guitar',
    tags: ['#Rocksmith', '#GuitarHero', '#Web3D', '#ThreeJS']
  }
];

// Use static data to ensure non-consecutive post rotation (idempotent step)
const staticData = $getWorkflowStaticData('global');
const lastIndex = staticData.lastPostIndex !== undefined ? staticData.lastPostIndex : -1;
let nextIndex = Math.floor(Math.random() * viralPosts.length);
if (viralPosts.length > 1 && nextIndex === lastIndex) {
  nextIndex = (nextIndex + 1) % viralPosts.length;
}
staticData.lastPostIndex = nextIndex;
staticData.lastPostAt = new Date().toISOString();

const selected = viralPosts[nextIndex];
let fullText = `${selected.hook}\n\n${selected.body}\n\n${selected.tags.join(' ')}`;

// Smart truncation to safely fit within Twitter/X 280 character limit
if (fullText.length > 280) {
  const excess = fullText.length - 277;
  fullText = fullText.substring(0, 277) + '...';
}

return [{
  json: {
    timestamp: staticData.lastPostAt,
    tweet_text: fullText,
    post_index: nextIndex,
    char_count: fullText.length
  }
}];

const execution = $json.execution || {};
const workflow = $json.workflow || {};
return [{
  json: {
    error_time: new Date().toISOString(),
    workflow_name: workflow.name || 'Gryf Autoposter',
    execution_id: execution.id || 'unknown',
    error_message: execution.error?.message || 'Unknown error occurred in workflow execution',
    status: 'dead_letter_logged'
  }
}];
